import { NextResponse } from 'next/server'
import type { NextRequest } from 'next/server'
import { randomUUID } from 'node:crypto'

export function proxy(request: NextRequest) {
  // Generate a unique request id for this response
  const requestId = randomUUID()

  // Log the incoming request pathname
  console.log(`[proxy] ${request.nextUrl.pathname}`)

  // Forward the request downstream with the new request header attached
  const requestHeaders = new Headers(request.headers)
  requestHeaders.set('x-request-id', requestId)

  const response = NextResponse.next({
    request: {
      headers: requestHeaders,
    },
  })

  // Add the custom response header so it is visible to clients
  response.headers.set('X-Request-Id', requestId)

  return response
}

export const config = {
  // Run on every request. Excluding Next.js internals prevents the header
  // and logging from interfering with static assets and image optimization.
  matcher: ['/((?!_next/static|_next/image|favicon.ico).*)'],
}

